"use client";

import React, { useState, useMemo, useRef, useEffect } from "react";
import { 
  Calendar as CalendarIcon, 
  ChevronDown, 
  CheckCircle2, 
  UploadCloud, 
  Plane, 
  Stethoscope, 
  Briefcase, 
  Baby, 
  Umbrella, 
  Heart, 
  AlertOctagon, 
  Trash2,
  ArrowRight,
  Clock,
  Sparkles
} from "lucide-react";

// --- CONFIGURATION ---
const HOLIDAYS = [{ date: "2026-01-26", name: "Republic Day" }];

const EXISTING_REQUESTS = [
  { date: "2026-01-05", status: "approved", label: "Sick" },
  { date: "2026-01-06", status: "approved", label: "Sick" },
  { date: "2026-01-15", status: "pending", label: "Casual" },
];

const LEAVE_TYPES = [
  { id: "annual", label: "Annual", icon: Plane, balance: 18, color: "text-blue-600", bg: "bg-blue-100/50", requiresDoc: false },
  { id: "sick", label: "Sick", icon: Stethoscope, balance: 12, color: "text-rose-600", bg: "bg-rose-100/50", requiresDoc: true },
  { id: "casual", label: "Casual", icon: Briefcase, balance: 6, color: "text-amber-600", bg: "bg-amber-100/50", requiresDoc: false },
  { id: "comp", label: "Comp Off", icon: Umbrella, balance: 3, color: "text-emerald-600", bg: "bg-emerald-100/50", requiresDoc: false },
  { id: "mat", label: "Maternity", icon: Baby, balance: 90, color: "text-purple-600", bg: "bg-purple-100/50", requiresDoc: true },
  { id: "ber", label: "Bereave", icon: Heart, balance: 5, color: "text-slate-600", bg: "bg-slate-100/50", requiresDoc: false },
  { id: "lop", label: "L.O.P", icon: AlertOctagon, balance: 0, color: "text-red-600", bg: "bg-red-100/50", requiresDoc: false },
];

const APPROVER_CHAIN = [
  { name: "Sarah J.", role: "Manager", avatar: "SJ", time: "4h" },
  { name: "HR Ops", role: "Audit", avatar: "HR", time: "24h" }
];

export default function PremiumAbsencePortal() {
  // --- STATE ---
  const [mode, setMode] = useState<"single" | "range" | "multi">("range");
  const [range, setRange] = useState<{ start: string; end: string }>({ start: "", end: "" });
  const [multiDates, setMultiDates] = useState<string[]>([]);
  const [typeId, setTypeId] = useState("annual");
  const [reason, setReason] = useState("");
  const [file, setFile] = useState<File | null>(null);
  const [isDropdownOpen, setIsDropdownOpen] = useState(false);
  const dropdownRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    function handleClickOutside(event: MouseEvent) {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setIsDropdownOpen(false);
      }
    }
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  const handleDateClick = (dateStr: string) => {
    if (mode === "multi") {
      setMultiDates(prev => prev.includes(dateStr) ? prev.filter(d => d !== dateStr) : [...prev, dateStr].sort());
    } else if (mode === "single") {
      setRange({ start: dateStr, end: dateStr });
    } else {
      if (!range.start || (range.start && range.end)) setRange({ start: dateStr, end: "" });
      else {
        const s = new Date(range.start);
        const e = new Date(dateStr);
        if (e < s) setRange({ start: dateStr, end: "" });
        else setRange({ ...range, end: dateStr });
      }
    }
  };

  // --- IMPROVEMENT: Quick Select Logic ---
  const handleQuickSelect = (type: 'today' | 'tomorrow' | 'next_week') => {
      setMode('range');
      const today = new Date();
      let target = new Date();
      
      if (type === 'tomorrow') target.setDate(today.getDate() + 1);
      if (type === 'next_week') target.setDate(today.getDate() + 7);
      
      const str = target.toISOString().split('T')[0];
      setRange({ start: str, end: str }); // Select single day range
  };

  const stats = useMemo(() => {
    let days = 0, deduction = 0;
    const checkDay = (dStr: string) => {
      const dObj = new Date(dStr);
      const isHoliday = HOLIDAYS.some(h => h.date === dStr);
      const isWeekend = dObj.getDay() === 0 || dObj.getDay() === 6;
      if (!isHoliday && !isWeekend) return 1;
      return 0;
    };
    if (mode === "multi") {
      days = multiDates.length;
      deduction = multiDates.reduce((acc, date) => acc + checkDay(date), 0);
    } else {
      if (!range.start || !range.end) return { days: 0, deduction: 0 };
      let cur = new Date(range.start);
      let end = new Date(range.end);
      while (cur <= end) {
        deduction += checkDay(cur.toISOString().split('T')[0]);
        days++;
        cur.setDate(cur.getDate() + 1);
      }
    }
    return { days, deduction };
  }, [range, multiDates, mode]);

  const selectedType = LEAVE_TYPES.find(t => t.id === typeId)!;
  const hasValidDates = mode === "multi" ? multiDates.length > 0 : !!(range.start && range.end);
  const isFormValid = hasValidDates && (!selectedType.requiresDoc || !!file);

  return (
    // PREMIUM BACKGROUND
    <div className="flex h-screen w-full bg-slate-50 dark:bg-[#050505] font-sans text-slate-800 dark:text-slate-200 overflow-hidden transition-colors duration-300 selection:bg-indigo-500/30">
      
      {/* Decorative Blur */}
      <div className="fixed top-[-20%] left-[-10%] w-[50%] h-[50%] bg-blue-500/5 rounded-full blur-[120px] pointer-events-none" />
      <div className="fixed bottom-[-20%] right-[-10%] w-[50%] h-[50%] bg-purple-500/5 rounded-full blur-[120px] pointer-events-none" />

      {/* --- LEFT: CALENDAR (70%) --- */}
      <div className="flex-1 flex flex-col p-4 gap-4 h-full min-w-0 z-10">
        
        {/* Floating Glass Header */}
        <div className="flex items-center justify-between shrink-0 bg-white/80 dark:bg-[#111]/80 backdrop-blur-xl px-5 py-3 rounded-2xl ring-1 ring-black/5 dark:ring-white/10 shadow-sm h-16 transition-all hover:shadow-md">
           <div className="flex items-center gap-3">
              <div className="bg-gradient-to-br from-indigo-500 to-purple-600 p-2 rounded-xl text-white shadow-lg shadow-indigo-500/20">
                  <CalendarIcon className="h-4 w-4" />
              </div>
              <div>
                <h1 className="text-sm font-bold text-slate-900 dark:text-white leading-tight tracking-tight">Absence<span className="opacity-50">Flow</span></h1>
                <p className="text-[10px] font-medium text-slate-500 dark:text-slate-400">Premium Portal</p>
              </div>
           </div>
           
           <div className="flex bg-slate-100/50 dark:bg-white/5 p-1 rounded-xl ring-1 ring-black/5 dark:ring-white/5">
              {['single', 'range', 'multi'].map((m) => (
                <button 
                  key={m}
                  onClick={() => { setMode(m as any); setRange({start:"", end:""}); setMultiDates([]); }}
                  className={`px-4 py-1.5 rounded-lg text-[10px] font-bold capitalize transition-all duration-300 ${
                    mode === m 
                    ? "bg-white dark:bg-[#222] shadow-sm text-indigo-600 dark:text-indigo-300 ring-1 ring-black/5 dark:ring-white/10" 
                    : "text-slate-500 hover:text-slate-700 dark:hover:text-slate-300"
                  }`}
                >
                  {m}
                </button>
              ))}
           </div>
        </div>

        {/* Premium Calendar Grid */}
        <div className="flex-1 bg-white/60 dark:bg-[#111]/60 backdrop-blur-md rounded-3xl ring-1 ring-black/5 dark:ring-white/5 shadow-sm flex flex-col overflow-hidden relative">
           
           {/* IMPROVEMENT: Quick Select Bar inside Calendar */}
           <div className="flex items-center justify-between px-6 py-4 border-b border-slate-100/50 dark:border-white/5 shrink-0 h-14">
              <div className="flex items-center gap-4">
                  <h2 className="text-base font-bold text-slate-800 dark:text-white tracking-tight">January 2026</h2>
                  
                  {/* Quick Select Pills */}
                  <div className="flex items-center gap-1 opacity-0 animate-in fade-in slide-in-from-left-4 duration-700 fill-mode-forwards" style={{ animationDelay: '200ms', opacity: 1 }}>
                     <button onClick={() => handleQuickSelect('today')} className="text-[9px] font-semibold bg-slate-100 dark:bg-white/5 hover:bg-slate-200 dark:hover:bg-white/10 text-slate-500 dark:text-slate-400 px-2 py-1 rounded-lg transition-colors">Today</button>
                     <button onClick={() => handleQuickSelect('tomorrow')} className="text-[9px] font-semibold bg-slate-100 dark:bg-white/5 hover:bg-slate-200 dark:hover:bg-white/10 text-slate-500 dark:text-slate-400 px-2 py-1 rounded-lg transition-colors">Tomorrow</button>
                  </div>
              </div>

              {(range.start || multiDates.length > 0) && (
                <button 
                  onClick={() => { setMultiDates([]); setRange({start:"", end:""}); }}
                  className="group flex items-center gap-1.5 text-[10px] font-bold text-rose-500 hover:text-rose-600 bg-rose-50 hover:bg-rose-100 dark:bg-rose-900/20 dark:hover:bg-rose-900/30 px-3 py-1.5 rounded-lg transition-all"
                >
                  <Trash2 className="h-3 w-3 transition-transform group-hover:scale-110" /> Clear
                </button>
              )}
           </div>

           <div className="flex-1 p-6 overflow-y-auto">
              <div className="grid grid-cols-7 gap-2 h-full content-start">
                 {['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'].map(d => (
                    <div key={d} className="text-center text-[10px] font-bold text-slate-400 dark:text-slate-500 uppercase tracking-wider mb-2">{d}</div>
                 ))}
                 
                 {[null, null, null].map((_, i) => <div key={`e-${i}`}/>)}

                 {Array.from({ length: 31 }).map((_, i) => {
                    const day = i + 1;
                    const dateStr = `2026-01-${day < 10 ? `0${day}` : day}`;
                    const holiday = HOLIDAYS.find(h => h.date === dateStr);
                    const isWeekend = new Date(2026, 0, day).getDay() % 6 === 0;
                    const existing = EXISTING_REQUESTS.find(r => r.date === dateStr);

                    let isSelected = false, inRange = false;
                    if (mode === "multi") isSelected = multiDates.includes(dateStr);
                    else {
                        isSelected = range.start === dateStr || range.end === dateStr;
                        inRange = range.start && range.end && dateStr > range.start && dateStr < range.end;
                    }

                    // --- PREMIUM STYLE LOGIC ---
                    let btnClass = "ring-1 ring-slate-100 dark:ring-white/5 bg-white dark:bg-[#151515] text-slate-600 dark:text-slate-400 hover:ring-indigo-300 dark:hover:ring-indigo-700 hover:bg-slate-50 dark:hover:bg-[#1a1a1a] transition-all duration-200";
                    let label = null;

                    if (existing) {
                        if (existing.status === 'approved') {
                            btnClass = "bg-emerald-50/50 dark:bg-emerald-900/10 ring-emerald-100 dark:ring-emerald-900/30 text-emerald-600 dark:text-emerald-400 cursor-default";
                            label = <span className="flex items-center gap-1 text-emerald-600 dark:text-emerald-400"><CheckCircle2 className="h-2 w-2"/> {existing.label}</span>;
                        } else {
                            btnClass = "bg-amber-50/50 dark:bg-amber-900/10 ring-amber-100 dark:ring-amber-900/30 text-amber-600 dark:text-amber-400 cursor-default";
                            label = <span className="flex items-center gap-1 text-amber-600 dark:text-amber-400"><Clock className="h-2 w-2"/> {existing.label}</span>;
                        }
                    } else if (isSelected) {
                        btnClass = "bg-gradient-to-br from-indigo-600 to-violet-600 text-white shadow-lg shadow-indigo-500/30 ring-0 scale-[1.03] z-10";
                    } else if (inRange) {
                        btnClass = "bg-indigo-50 dark:bg-indigo-900/10 text-indigo-600 dark:text-indigo-300 ring-indigo-100 dark:ring-indigo-900/30";
                    } else if (holiday) {
                        btnClass = "bg-rose-50/50 dark:bg-rose-900/10 ring-rose-100 dark:ring-rose-900/30 text-rose-600 dark:text-rose-400";
                        label = holiday.name;
                    } else if (isWeekend) {
                        btnClass = "bg-slate-50/50 dark:bg-[#111]/50 text-slate-300 dark:text-slate-600 ring-transparent";
                    }

                    return (
                       <button
                         key={day}
                         onClick={() => handleDateClick(dateStr)}
                         disabled={!!existing}
                         className={`relative h-full max-h-24 min-h-[3.5rem] rounded-xl text-left p-2 group ${btnClass}`}
                       >
                          <span className={`text-xs font-bold leading-none ${isSelected ? 'text-white' : ''}`}>{day}</span>
                          {label && (
                            <span className={`absolute bottom-2 left-2 right-2 text-[9px] font-bold px-1.5 py-0.5 rounded truncate ${isSelected ? 'bg-white/20 text-white backdrop-blur-md' : 'bg-white/50 dark:bg-black/20 backdrop-blur-sm'}`}>
                                {label}
                            </span>
                          )}
                          {isSelected && <span className="absolute top-2 right-2"><Sparkles className="h-3 w-3 text-indigo-200 animate-pulse" /></span>}
                       </button>
                    )
                 })}
              </div>
           </div>
        </div>
      </div>

      {/* --- RIGHT: SIDEBAR (30%) --- */}
      <div className="w-[360px] flex-none p-4 pl-0 flex flex-col gap-4 h-full z-20">
         
         {/* 1. Request Form Card */}
         <div className="flex-1 bg-white/80 dark:bg-[#111]/80 backdrop-blur-xl rounded-3xl ring-1 ring-black/5 dark:ring-white/10 shadow-lg flex flex-col overflow-hidden">
            
            <div className="p-5 border-b border-slate-100/50 dark:border-white/5 shrink-0 space-y-5">
               
               {/* Custom Dropdown */}
               <div className="relative" ref={dropdownRef}>
                  <label className="text-[10px] font-bold uppercase text-slate-400 dark:text-slate-500 mb-2 block tracking-wider">Leave Type</label>
                  <button 
                    onClick={() => setIsDropdownOpen(!isDropdownOpen)}
                    className="w-full flex items-center justify-between bg-white dark:bg-[#1a1a1a] ring-1 ring-slate-200 dark:ring-white/10 rounded-xl p-3 hover:ring-indigo-400 transition-all shadow-sm"
                  >
                     <div className="flex items-center gap-3">
                        <div className={`p-1.5 rounded-lg ${selectedType.bg} ${selectedType.color}`}><selectedType.icon className="h-4 w-4" /></div>
                        <span className="text-sm font-bold text-slate-800 dark:text-white">{selectedType.label}</span>
                     </div>
                     <ChevronDown className={`h-4 w-4 text-slate-400 transition-transform ${isDropdownOpen ? 'rotate-180' : ''}`} />
                  </button>

                  {isDropdownOpen && (
                     <div className="absolute top-full left-0 right-0 mt-2 bg-white dark:bg-[#1a1a1a] ring-1 ring-black/5 dark:ring-white/10 rounded-xl shadow-2xl z-50 max-h-[300px] overflow-y-auto p-1 custom-scrollbar">
                        {LEAVE_TYPES.map(t => (
                           <button
                             key={t.id}
                             onClick={() => { setTypeId(t.id); setIsDropdownOpen(false); }}
                             className="w-full flex items-center justify-between p-3 hover:bg-slate-50 dark:hover:bg-white/5 rounded-lg group transition-colors"
                           >
                              <div className="flex items-center gap-3">
                                 <div className={`p-1.5 rounded-lg ${t.bg} ${t.color}`}><t.icon className="h-4 w-4" /></div>
                                 <span className="text-sm font-medium text-slate-700 dark:text-slate-300 group-hover:text-slate-900 dark:group-hover:text-white">{t.label}</span>
                              </div>
                              <span className="text-[10px] font-bold text-slate-400 bg-slate-100 dark:bg-white/10 px-2 py-1 rounded-md">{t.balance}</span>
                           </button>
                        ))}
                     </div>
                  )}
               </div>

               {/* Stats Card */}
               <div className="flex justify-between bg-slate-50 dark:bg-white/5 p-4 rounded-xl items-center ring-1 ring-black/5 dark:ring-white/5">
                  <div className="text-center w-1/2 border-r border-slate-200 dark:border-white/10 pr-2">
                     <p className="text-[10px] font-bold text-slate-400 uppercase tracking-wider">Days Selected</p>
                     <p className="text-xl font-black text-slate-900 dark:text-white mt-1">{stats.days}</p>
                  </div>
                  <div className="text-center w-1/2 pl-2">
                     <p className="text-[10px] font-bold text-slate-400 uppercase tracking-wider">Net Deduction</p>
                     <p className="text-xl font-black text-rose-500 mt-1">-{stats.deduction}</p>
                  </div>
               </div>
            </div>

            {/* Form Inputs */}
            <div className="flex-1 p-5 space-y-5 overflow-y-auto custom-scrollbar">
               <div>
                  <label className="text-[10px] font-bold uppercase text-slate-400 dark:text-slate-500 mb-2 block tracking-wider">Reason</label>
                  <textarea 
                     className="w-full h-24 rounded-xl bg-slate-50 dark:bg-white/5 p-3 text-xs font-medium text-slate-900 dark:text-white focus:ring-2 focus:ring-indigo-500 focus:bg-white dark:focus:bg-black outline-none resize-none transition-all placeholder:text-slate-400 dark:placeholder:text-slate-600"
                     placeholder="Share context for your absence..."
                     value={reason}
                     onChange={(e) => setReason(e.target.value)}
                  />
               </div>

               {selectedType.requiresDoc && (
                  <div className="animate-in zoom-in-95 duration-300">
                     <label className="text-[10px] font-bold uppercase text-slate-400 dark:text-slate-500 mb-2 block flex justify-between tracking-wider">
                        <span>Attachment</span> <span className="text-rose-500 dark:text-rose-400">* Required</span>
                     </label>
                     <div 
                        onClick={() => fileInputRef.current?.click()}
                        className={`border-2 border-dashed rounded-xl h-16 flex items-center justify-center cursor-pointer transition-all gap-3 group ${
                           file 
                           ? "border-emerald-500 bg-emerald-50 dark:bg-emerald-900/10" 
                           : "border-slate-200 dark:border-white/10 hover:border-indigo-400 dark:hover:border-indigo-500 hover:bg-slate-50 dark:hover:bg-white/5"
                        }`}
                     >
                        <input type="file" className="hidden" ref={fileInputRef} onChange={(e) => e.target.files && setFile(e.target.files[0])} />
                        {file ? (
                           <span className="text-xs font-bold text-emerald-600 dark:text-emerald-400 flex items-center gap-2"><CheckCircle2 className="h-4 w-4"/> {file.name.slice(0, 15)}...</span>
                        ) : (
                           <>
                             <div className="bg-slate-100 dark:bg-white/10 p-2 rounded-full text-slate-400 group-hover:text-indigo-500 group-hover:scale-110 transition-transform">
                                <UploadCloud className="h-4 w-4" />
                             </div>
                             <span className="text-[10px] font-bold text-slate-500 dark:text-slate-400 group-hover:text-indigo-500">Upload Proof</span>
                           </>
                        )}
                     </div>
                  </div>
               )}
            </div>
            
            {/* Submit & Approver */}
            <div className="p-5 border-t border-slate-100/50 dark:border-white/5 bg-slate-50/50 dark:bg-white/5 shrink-0">
               <button 
                  disabled={!isFormValid}
                  className={`w-full py-4 rounded-xl font-bold text-sm shadow-lg shadow-indigo-500/20 transition-all flex items-center justify-center gap-2 group ${
                    isFormValid 
                    ? "bg-slate-900 dark:bg-indigo-600 text-white hover:scale-[1.02] hover:shadow-indigo-500/30" 
                    : "bg-slate-200 dark:bg-white/10 text-slate-400 dark:text-slate-600 cursor-not-allowed"
                  }`}
               >
                  {isFormValid ? "Submit Request" : "Complete Details"}
                  {isFormValid && <ArrowRight className="h-4 w-4 group-hover:translate-x-1 transition-transform" />}
               </button>
            </div>
         </div>

         {/* 2. RESTORED: Approver Chain (Glass Card) */}
         <div className="bg-white/60 dark:bg-[#111]/60 backdrop-blur-md rounded-2xl ring-1 ring-black/5 dark:ring-white/5 p-4 shadow-sm shrink-0">
            <h3 className="text-[10px] font-bold uppercase tracking-widest text-slate-400 dark:text-slate-500 mb-3 flex items-center gap-2">
                <Zap className="h-3 w-3 text-amber-500" /> Approval Flow
            </h3>
            <div className="flex items-center gap-2 relative">
               {/* Connecting Line */}
               <div className="absolute top-1/2 left-0 right-0 h-px bg-slate-200 dark:bg-white/10 -z-10" />
               
               {APPROVER_CHAIN.map((p, i) => (
                  <React.Fragment key={i}>
                     <div className="flex items-center gap-3 bg-white dark:bg-[#1a1a1a] p-2 pr-4 rounded-xl ring-1 ring-black/5 dark:ring-white/10 shadow-sm flex-1 min-w-0">
                        <div className="h-8 w-8 rounded-full bg-gradient-to-br from-slate-100 to-slate-200 dark:from-white/10 dark:to-white/5 flex items-center justify-center text-[10px] font-bold text-slate-600 dark:text-slate-300 ring-2 ring-white dark:ring-[#111]">{p.avatar}</div>
                        <div className="min-w-0">
                           <p className="text-[10px] font-bold text-slate-900 dark:text-white truncate leading-tight">{p.name}</p>
                           <p className="text-[9px] text-slate-400 dark:text-slate-500 leading-tight">~{p.time}</p>
                        </div>
                     </div>
                     {i < APPROVER_CHAIN.length - 1 && <div className="bg-white dark:bg-[#1a1a1a] p-1 rounded-full ring-1 ring-black/5 dark:ring-white/10"><ArrowRight className="h-3 w-3 text-slate-400" /></div>}
                  </React.Fragment>
               ))}
            </div>
         </div>

      </div>
    </div>
  );
}